import {realismFor} from './realism.js';
import {PRODUCTS,printers,specFor,hasSkill,skillPoints,SKILLS,lifetimeKpis,machineKpis} from './model.js';
import {AD_CHANNELS} from './advertising.js';
import {productionPlan,goodsFor} from './creations.js';
import {creationPicture} from './creations-ui.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>(Number(v)||0).toLocaleString('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:2});
const number=(v,n=1)=>(Number(v)||0).toLocaleString('fr-FR',{maximumFractionDigits:n});
const hours=v=>number(v/60,1)+' h';
export function skillsPanel(s){const points=skillPoints(s);return `<div class="skills-intro"><span>✦</span><div><b>${points.available} point(s) disponibles</b><p>Un point au départ, puis un point tous les 100 XP. L’expérience vient des impressions, des prototypes et des entraînements.</p></div></div><div class="skill-branches">${[['production','Les outils'],['atelier','L’atelier'],['commerce','Le commerce']].map(([id,title])=>`<section><h3>${title}</h3>${SKILLS.filter(n=>n.branch===id).map(n=>{const owned=hasSkill(s,n.id),ready=n.requires.every(id=>hasSkill(s,id));return `<article class="skill-node ${owned?'is-owned':ready?'is-ready':'is-locked'}"><span>${owned?'✓':'✦ '+n.cost}</span><h4>${n.name}</h4><p>${n.description}${n.requires.length?`<small class="skill-prerequisite">Après : ${n.requires.map(id=>SKILLS.find(v=>v.id===id).name).join(', ')}</small>`:''}</p><button class="button ${owned?'secondary':'primary'} small" data-action="learn-skill" data-id="${n.id}" ${owned||!ready||points.available<n.cost?'disabled':''}>${owned?'Acquis':!ready?'Prérequis à acquérir':'Apprendre · '+n.cost+' pt'}</button></article>`;}).join('')}</section>`).join('')}</div><p class="management-note">Les compétences améliorent la méthode et débloquent les outils. Un plateau de six objets ne devient pas six imprimantes : le temps d’extrusion de chaque pièce reste compté.</p>`;}
export function machineDashboard(s){return `<div class="management-heading"><div><span class="eyebrow">LE RENDEMENT DE L’ATELIER</span><h2>Ce que font tes machines.</h2></div><button class="button secondary small" data-action="skills">✦ Compétences</button></div><p class="management-note">Les montants proviennent des ventes livrées. Le stock et les impressions en cours ne sont pas des revenus. La contribution directe retire filament, énergie, entretien et frais des ventes ; les frais fixes restent dans le bilan global.</p><div class="machine-cards">${printers(s).map(m=>{const k=machineKpis(s,m),job=s.orders.find(o=>o.id===m.job),n=m.plate?.length||1,pct=m.total?Math.max(0,100*(1-m.remaining/m.total)):0;return `<article class="machine-business-card"><header><span class="machine-state ${m.job?'is-running':''}"></span><h3>${esc(specFor(m).name)}</h3><span>${m.broken?'À réparer':job?job.status==='loading'?'Chargement':'En impression':'Disponible'}</span></header>${job?`<div class="live-plate"><b>${n} objet(s) sur le plateau</b><span>${number(pct,0)} % · ${hours(m.remaining)} restantes</span><div><i style="width:${pct}%"></i></div><small>Plateau occupé à ${number(m.plateFill||0,0)} % · une extrusion partagée</small></div>`:'<div class="machine-wait">Une commande ou un lot de stock peut occuper ce créneau.</div>'}<div class="machine-business-values"><div><strong>${money(k.averageRevenue)}</strong><span>CA livré / jour moyen</span></div><div><strong class="${k.averageContribution<0?'is-negative':''}">${money(k.averageContribution)}</strong><span>contribution / jour moyen</span></div><div><strong>${number(k.utilization,1)} %</strong><span>occupation sur 7 jours</span></div><div><strong>${money(k.revenuePerHour)}</strong><span>CA livré / heure machine</span></div></div><dl class="business-facts"><div><dt>Heures imprimées</dt><dd>${number(k.hours)} h</dd></div><div><dt>Produits imprimés / plateaux</dt><dd>${k.units} / ${k.plates}</dd></div><div><dt>Filament engagé / heure</dt><dd>${number(k.filamentPerHour)} g/h</dd></div><div><dt>Énergie mesurée dans le jeu</dt><dd>${number(k.kWh,2)} kWh · ${money(k.energy)}</dd></div><div><dt>Matière + entretien</dt><dd>${money(k.materials+k.maintenance)}</dd></div><div><dt>CA livré attribué</dt><dd>${money(k.revenue)}</dd></div><div><dt>Plateaux ratés</dt><dd>${k.failures}</dd></div><div><dt>Retour sur achat, rythme actuel</dt><dd>${k.paybackDays===null?'Pas encore estimable':k.paybackDays===0?'Achat couvert':number(k.paybackDays,0)+' j estimés'}</dd></div></dl><button class="button secondary small" data-action="inspect-machine" data-id="${m.id}">Réglages et entretien →</button></article>`;}).join('')||'<div class="creation-empty"><h3>La première machine donnera le rythme.</h3><p>Aménage ton atelier pour commencer.</p></div>'}</div><p class="management-note">L’attribution des ventes par machine démarre avec cette évolution. Les heures antérieures sont conservées. Les frais fixes, ton temps et les invendus peuvent rendre le résultat global inférieur à la contribution des machines.</p>`;}
export function lifetimeSummary(s){const k=lifetimeKpis(s);return `<div class="management-heading"><div><span class="eyebrow">${k.coverageFrom?'HISTORIQUE CONSERVÉ':'DEPUIS LE DÉBUT'}</span><h2>Chaque couche compte.</h2></div><button class="button secondary small" data-action="finance-mode" data-mode="machines">Rendement des machines →</button></div><div class="lifetime-grid">${[['CA livré',k.revenue,'Ventes et port comptabilisés à la livraison.'],['Coûts cumulés',k.cost,'Matière consommée, frais, taxes provisionnées et amortissements.'],['Résultat cumulé',k.profit,'Le coût du temps personnel est affiché à part.'],['CA moyen / jour',k.averageRevenue,'Moyenne par jour calendaire, jours vides inclus.'],['Bénéfice moyen / jour',k.averageProfit,'Résultat divisé par la durée observée.'],['Après ton temps personnel',k.economicProfit,number(k.human)+' h valorisées à '+realismFor(s).hourValue+' €/h.']].map(([name,value,note])=>`<article><span>${name}</span><strong class="${value<0?'is-negative':''}">${money(value)}</strong><small>${note}</small></article>`).join('')}</div><div class="lifetime-details"><span><b>${s.metrics.completed}</b> commandes livrées</span><span><b>${number(k.human)} h</b> de travail personnel</span><span><b>${money(k.inflow)}</b> entrées de caisse</span><span><b>${money(k.outflow)}</b> sorties de caisse</span><span><b>${money(s.totalOwnerDraw)}</b> retirés personnellement</span><span><b>${number(s.energy.kWh,2)} kWh</b> depuis le début</span></div>${k.coverageFrom?'<p class="management-note">Cette ancienne sauvegarde ne conservait plus tout le détail de ses premières années. Les cumuls repris couvrent l’historique encore disponible ; les nouvelles opérations resteront cumulées.</p>':''}`;}
export function financeTabs(mode){return `<div class="management-tabs">${[['lifetime','Depuis le début'],['recent','30 derniers jours'],['machines','Les machines']].map(([id,label])=>`<button data-action="finance-mode" data-mode="${id}" aria-pressed="${mode===id}">${label}</button>`).join('')}</div>`;}
export function storefrontPage(s,tab='shop'){const all=[...PRODUCTS,...s.studio.products];return `<div class="management-heading"><div><span class="eyebrow">UNE VITRINE À TON IMAGE</span><h2>Ma boutique.</h2></div><button class="button secondary small" data-action="creations-panel">Créer des objets →</button></div><div class="management-tabs"><button data-action="shop-mode" data-mode="shop" aria-pressed="${tab==='shop'}">Catalogue & vedettes</button><button data-action="shop-mode" data-mode="ads" aria-pressed="${tab==='ads'}">Publicité</button></div>${tab==='ads'?adsPage(s,all):shopCatalogue(s,all)}`;}
function shopCatalogue(s,all){const limit=hasSkill(s,'merchandising')?5:3;return `<div class="store-preview"><span class="eyebrow">EN VITRINE · ${s.storefront.featured.length} / ${limit}</span><div>${s.storefront.featured.length?s.storefront.featured.map(id=>{const p=all.find(p=>p.id===id);return p?`<article>${creationPicture(p.id,p.color)}<b>${esc(p.name)}</b><span>${money(p.price)}</span></article>`:'';}).join(''):'<p>Choisis quelques vedettes ci-dessous. Elles prennent davantage de place dans les demandes, sans créer une clientèle infinie.</p>'}</div></div><section class="own-shop compact-shop"><div><h3>Ma boutique personnelle</h3><p>${s.website.stage==='live'?'En ligne · hébergement gratuit dans le jeu. Paiement : 2,5 % + 0,25 € par commande.':s.website.stage==='building'?'Création en cours · '+hours(s.website.work)+' de travail restant.':'Après 8 livraisons : 0 € de création, 8 h de travail personnel.'}</p></div>${s.website.stage==='locked'?`<button class="button primary small" data-action="website" ${s.metrics.completed<8?'disabled':''}>Créer · 0 €</button>`:''}</section><div class="shop-product-list">${all.map(p=>{const owned=s.studio.products.includes(p),visible=!s.storefront.disabled.includes(p.id),listed=!owned||p.listed,featured=s.storefront.featured.includes(p.id),locked=p.requiresSkill&&!hasSkill(s,p.requiresSkill),etsy=['Catalogue','Petite série'].includes(p.category)&&p.origin!=='licensed';return `<article class="shop-product-row"><div class="shop-product-art">${creationPicture(p.id,p.color)}</div><div class="shop-product-copy"><h3>${esc(p.name)}</h3><p>${money(p.price)} · ${owned?goodsFor(s,p.id)+' prêts':esc(p.category)}${locked?' · Grand format requis':''}</p><div class="product-channel-options">${[['etsy','Etsy'],['local','Direct'],['site','Ma boutique']].map(([id,label])=>`<label><input type="checkbox" data-product-channel="${p.id}" data-channel="${id}" ${(id!=='etsy'||etsy)&&s.storefront.channels[p.id]?.[id]!==false?'checked':''} ${id==='etsy'&&!etsy?'disabled':''}>${label}</label>`).join('')}</div></div><div class="shop-product-switches"><label><input type="checkbox" data-product-visible="${p.id}" ${visible?'checked':''} ${!listed||locked?'disabled':''}>Visible</label><label class="feature-toggle"><input type="checkbox" data-product-featured="${p.id}" ${featured?'checked':''} ${!listed||locked?'disabled':''}>✦ Vedette</label>${!listed?`<button class="text-button" data-action="list-creation" data-id="${p.id}" ${p.listingQueued?'disabled':''}>${p.listingQueued?'Fiche en cours…':'Mettre en vente · 15 min'}</button>`:''}</div></article>`;}).join('')}</div><p class="management-note">Les créations sous licence tierce restent hors Etsy dans cette simulation. Masquer un produit arrête ses nouvelles demandes ; les engagements déjà acceptés restent à honorer.</p>`;}
function campaignCard(c,active=false){const type=AD_CHANNELS[c.channel]||{name:'Campagne'},roas=c.spent?c.revenue/c.spent:0;return `<article class="ad-report"><header><span>${type.name}</span><b>${active?c.days+' jour(s) restants':c.reason||'Terminée'}</b></header><div>${[['Dépensé',money(c.spent)],['Clics',number(c.clicks,0)],['Demandes',c.inquiries||0],['Livraisons',c.orders||0],['CA attribué',money(c.revenue)],['ROAS',number(roas,2)+'×']].map(([label,v])=>`<span><b>${v}</b><small>${label}</small></span>`).join('')}</div>${active?'<button class="button secondary small" data-action="campaign" data-channel="none">Arrêter la campagne</button>':''}</article>`;}
function adsPage(s,all){const active=s.campaign.channel!=='none';return `<p class="management-note">Une campagne active à la fois. Tu choisis son budget, sa durée et sa cible. Les clics, la conversion et le coût par clic sont des hypothèses du jeu ; aucune publicité réelle n’est achetée.</p><form id="campaign-form" class="campaign-form"><div><label>Canal<select name="channel">${Object.entries(AD_CHANNELS).map(([id,v])=>`<option value="${id}" ${id==='google'&&s.website.stage!=='live'?'disabled':''}>${v.name}${id==='google'&&s.website.stage!=='live'?' · boutique requise':''}</option>`).join('')}</select></label><label>Budget / jour<input name="budget" type="number" min="1" max="50" step="1" value="6" required><small>1 à 50 €, sans entamer la réserve.</small></label><label>Durée en jours<input name="days" type="number" min="1" max="30" value="7" required></label><label>Mettre en avant<select name="target"><option value="all">Toute ma vitrine</option>${all.filter(p=>!s.storefront.disabled.includes(p.id)&&(!s.studio.products.includes(p)||p.listed)&&(!p.requiresSkill||hasSkill(s,p.requiresSkill))).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label></div><button class="button primary" type="submit">${active?'Remplacer la campagne':'Lancer la campagne simulée'}</button><small>Le budget est débité progressivement, par créneaux horaires. Arrêt automatique à l’échéance ou si la réserve est menacée.</small></form>${active?campaignCard(s.campaign,true):'<div class="empty-line">Aucune campagne en cours. La clientèle organique continue d’évoluer avec la réputation.</div>'}<h3 class="management-section-title">Mes dernières campagnes</h3>${s.marketing.history.slice(0,6).map(c=>campaignCard(c)).join('')||'<p class="management-note">Les premiers résultats apparaîtront ici. Un ROAS élevé ne tient pas compte des coûts de fabrication ni des impôts.</p>'}`;}
export function machineQuickStats(s,m){const k=machineKpis(s,m);return `<div class="machine-quick-stats"><span><b>${money(k.averageRevenue)}</b><small>CA livré / jour</small></span><span><b>${number(k.utilization)} %</b><small>occupation · 7 j</small></span><span><b>${money(k.revenuePerHour)}</b><small>CA / h machine</small></span></div><button class="button secondary small machine-dashboard-link" data-action="machine-dashboard">Voir tous les rendements →</button>`;}
